+
+/* ACTIONS */
+
+.actions {
+    padding: 10px;
+    background: var(--body-bg);
+    border-top: none;
+    border-bottom: none;
+    line-height: 1.5rem;
+    color: var(--body-quiet-color);
+    width: 100%;
+    box-sizing: border-box;
+}
+
+.actions span.all,
+.actions span.action-counter,
+.actions span.clear,
+.actions span.question {
+    font-size: 0.8125rem;
+    margin: 0 0.5em;
+}
+
+.actions:last-child {
+    border-bottom: none;
+}
+
+.actions select {
+    vertical-align: top;
+    height: 1.5rem;
+    color: var(--body-fg);
+    border: 1px solid var(--border-color);
+    border-radius: 4px;
+    font-size: 0.875rem;
+    padding: 0 0 0 4px;
+    margin: 0;
+    margin-left: 10px;
+}
+
+.actions select:focus {
+    border-color: var(--body-quiet-color);
+}
+
+.actions label {
+    display: inline-block;
+    vertical-align: middle;
+    font-size: 0.8125rem;
+}
+
+.actions .button {
+    font-size: 0.8125rem;
