+    cursor: pointer;
+    height: 1.5rem;
+    line-height: 1;
+    padding: 4px 8px;
+    margin: 0;
+    color: var(--body-fg);
+}
+
+.actions .button:focus,
+.actions .button:hover {
+    border-color: var(--body-quiet-color);
+}

